def seed_ai_roles(db_path=DEFAULT_DB_PATH):
    conn = connect(db_path)
    cursor = conn.cursor()
    total = 0
    for topic_id, items in AI_ROLE_QUESTIONS.items():
        cursor.execute("DELETE FROM questions WHERE topic_id = ?", (topic_id,))
        rows = [
            (topic_id, diff, qtype, q, a, h)
            for (diff, qtype, q, a, h) in items
        ]
        cursor.executemany(
            "INSERT INTO questions (topic_id, difficulty, type, question, answer, hint) VALUES (?, ?, ?, ?, ?, ?)",
            rows,
        )
        total += len(rows)
    conn.commit()
    conn.close()
    print(f"Seeded {total} AI role questions across {len(AI_ROLE_QUESTIONS)} AI tracks.")
    return total


if __name__ == "__main__":
    seed_ai_roles()

